package com.example.editor.policy.bundle;

import java.nio.file.Files;
import java.nio.file.Path;
import java.time.Instant;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import org.springframework.stereotype.Service;
import com.example.editor.metamodel.importing.updatesite.UpdateSiteMirrorChannel;
import com.example.editor.policy.HydraPolicyEvaluationRequest;
import com.example.editor.policy.HydraPolicyEvaluationReport;
import com.example.editor.policy.HydraPolicyRule;
import com.example.editor.policy.HydraPolicyService;
import com.example.editor.policy.HydraRevocationEntry;
import com.example.editor.persistence.support.HydraPersistenceSupport;
import tools.jackson.databind.ObjectMapper;
import tools.jackson.databind.ObjectWriter;
import tools.jackson.databind.SerializationFeature;

/** BD immutable policy bundles, simulation, channel activation, history and revocation. */
@Service
public class HydraPolicyBundleService {
    private final HydraPolicyService policies; private final HydraPolicyBundleProperties properties;
    private final ObjectMapper mapper; private final ObjectWriter writer;
    /** Descripción: Inicializa una instancia de HydraPolicyBundleService con sus dependencias y datos de entrada. Entradas: policies: dato de entrada necesario para la operación; properties: configuración que gobierna el comportamiento; mapper: componente de conversión utilizado durante el procesamiento. Salida: deja la instancia inicializada y lista para su uso. */ public HydraPolicyBundleService(HydraPolicyService policies,HydraPolicyBundleProperties properties,ObjectMapper mapper){this.policies=policies;this.properties=properties;this.mapper=mapper;this.writer=mapper.writer(SerializationFeature.ORDER_MAP_ENTRIES_BY_KEYS);}
    public synchronized HydraPolicyBundle save(HydraPolicyBundleRequest request){
        if(request==null)throw new IllegalArgumentException("Policy bundle request is required"); String id=HydraPersistenceSupport.safeId(request.bundleId(),"bundleId"),version=HydraPersistenceSupport.safeId(request.version(),"version");
        UpdateSiteMirrorChannel channel=request.channel()==null?UpdateSiteMirrorChannel.INTERNAL:request.channel();
        validateRules(request.rules()); validateRevocations(request.revocations());
        String attestation=attestation(id,version,channel,request.rules(),request.revocations(),request.annotations());
        Path path=bundlePath(id,version); if(Files.isRegularFile(path)){HydraPolicyBundle existing=read(path,HydraPolicyBundle.class,"Policy bundle version is invalid");if(!existing.attestationSha256().equals(attestation))throw new IllegalStateException("Policy bundle versions are immutable");return existing;}
        HydraPolicyBundle bundle=new HydraPolicyBundle(id,version,channel,HydraPolicyBundleStatus.DRAFT,request.rules(),request.revocations(),attestation,"",request.annotations(),Instant.now(),null,null);write(path,bundle);HydraPersistenceSupport.trim(bundlesRoot(),properties.getMaximumVersions());return bundle;
    }
    /** Descripción: Ejecuta la operación «simulate» correspondiente a la responsabilidad de HydraPolicyBundleService. Entradas: bundleId: identificador que delimita el recurso objetivo; version: dato de entrada necesario para la operación; request: solicitud con los datos necesarios para ejecutar la operación. Salida: devuelve el resultado definido por el contrato del método. */ public HydraPolicyBundleSimulationReport simulate(String bundleId,String version,HydraPolicyBundleSimulationRequest request){
        HydraPolicyBundle bundle=find(bundleId,version);if(bundle.status()==HydraPolicyBundleStatus.REVOKED)throw new IllegalStateException("Revoked policy bundles cannot be simulated");
        List<HydraPolicyEvaluationReport> evaluations=new ArrayList<>();List<String> diagnostics=new ArrayList<>();
        if(request==null||request.provenanceReportIds().isEmpty())diagnostics.add("At least one AV provenance report is required");
        else for(String reportId:request.provenanceReportIds())try{evaluations.add(policies.evaluate(new HydraPolicyEvaluationRequest(reportId,request.includeWarnings()),bundle.rules(),bundle.revocations()));}catch(RuntimeException exception){diagnostics.add(reportId+": "+exception.getMessage());}
        boolean allowed=diagnostics.isEmpty()&&evaluations.stream().allMatch(HydraPolicyEvaluationReport::allowed);
        if(bundle.channel()==UpdateSiteMirrorChannel.STABLE&&bundle.rules().stream().anyMatch(rule->!rule.enabled())){allowed=false;diagnostics.add("STABLE policy bundles cannot contain disabled rules");}
        String evidence=HydraPersistenceSupport.fingerprint(writer,Map.of("bundleAttestation",bundle.attestationSha256(),"evaluations",evaluations,"diagnostics",diagnostics));
        HydraPolicyBundleSimulationReport report=new HydraPolicyBundleSimulationReport("policy-sim-"+evidence.substring(0,20),bundle.bundleId(),bundle.version(),allowed,evaluations,diagnostics,bundle.attestationSha256(),Instant.now());write(simulationPath(report.reportId()),report);HydraPersistenceSupport.trim(simulationsRoot(),properties.getMaximumSimulations());return report;
    }
    public synchronized HydraPolicyBundle activate(String bundleId,String version,HydraPolicyBundleActivationRequest request){
        HydraPolicyBundle bundle=find(bundleId,version);if(request==null)throw new IllegalArgumentException("Simulation report is required");HydraPolicyBundleSimulationReport simulation=simulation(request.simulationReportId());
        if(!simulation.allowed()||!simulation.bundleId().equals(bundle.bundleId())||!simulation.version().equals(bundle.version())||!simulation.bundleAttestationSha256().equals(bundle.attestationSha256()))throw new IllegalStateException("Policy bundle activation requires matching successful simulation evidence");
        for(HydraPolicyBundle current:bundles())if(current.status()==HydraPolicyBundleStatus.ACTIVE&&current.channel()==bundle.channel()&&!same(current,bundle))write(bundlePath(current.bundleId(),current.version()),copy(current,HydraPolicyBundleStatus.DRAFT,current.revocationReason(),current.activatedAt(),current.revokedAt()));
        HydraPolicyBundle active=copy(bundle,HydraPolicyBundleStatus.ACTIVE,"",Instant.now(),null);write(bundlePath(active.bundleId(),active.version()),active);return active;
    }
    public synchronized HydraPolicyBundle revoke(String bundleId,String version,HydraPolicyBundleRevocationRequest request){HydraPolicyBundle bundle=find(bundleId,version);String reason=request==null?"":HydraPersistenceSupport.text(request.reason());if(reason.isBlank())throw new IllegalArgumentException("Revocation reason is required");HydraPolicyBundle revoked=copy(bundle,HydraPolicyBundleStatus.REVOKED,reason,bundle.activatedAt(),Instant.now());write(bundlePath(revoked.bundleId(),revoked.version()),revoked);return revoked;}
    /** Descripción: Ejecuta la operación «active» correspondiente a la responsabilidad de HydraPolicyBundleService. Entradas: channel: dato de entrada necesario para la operación. Salida: devuelve el resultado definido por el contrato del método. */ public HydraPolicyBundle active(UpdateSiteMirrorChannel channel){return bundles().stream().filter(value->value.channel()==channel&&value.status()==HydraPolicyBundleStatus.ACTIVE).max(Comparator.comparing(HydraPolicyBundle::activatedAt,Comparator.nullsFirst(Comparator.naturalOrder()))).orElseThrow(()->new IllegalArgumentException("No active policy bundle for channel"));}
    /** Descripción: Ejecuta la operación «bundles» correspondiente a la responsabilidad de HydraPolicyBundleService. Entradas: no requiere parámetros de entrada. Salida: devuelve el resultado definido por el contrato del método. */ public List<HydraPolicyBundle> bundles(){return readAll(bundlesRoot(),HydraPolicyBundle.class).stream().sorted(Comparator.comparing(HydraPolicyBundle::createdAt).reversed()).toList();}
    /** Descripción: Ejecuta la operación «simulations» correspondiente a la responsabilidad de HydraPolicyBundleService. Entradas: no requiere parámetros de entrada. Salida: devuelve el resultado definido por el contrato del método. */ public List<HydraPolicyBundleSimulationReport> simulations(){return readAll(simulationsRoot(),HydraPolicyBundleSimulationReport.class).stream().sorted(Comparator.comparing(HydraPolicyBundleSimulationReport::simulatedAt).reversed()).toList();}
    /** Descripción: Obtiene la información correspondiente a «find» dentro de HydraPolicyBundleService. Entradas: id: identificador que delimita el recurso objetivo; version: dato de entrada necesario para la operación. Salida: devuelve el resultado definido por el contrato del método. */ public HydraPolicyBundle find(String id,String version){String safeId=HydraPersistenceSupport.safeId(id,"bundleId"),safeVersion=HydraPersistenceSupport.safeId(version,"version");return read(bundlePath(safeId,safeVersion),HydraPolicyBundle.class,"Policy bundle version was not found");}
    /** Descripción: Ejecuta la operación «simulation» correspondiente a la responsabilidad de HydraPolicyBundleService. Entradas: id: identificador que delimita el recurso objetivo. Salida: devuelve el resultado definido por el contrato del método. */ public HydraPolicyBundleSimulationReport simulation(String id){return read(simulationPath(HydraPersistenceSupport.safeId(id,"simulationReportId")),HydraPolicyBundleSimulationReport.class,"Policy simulation report was not found");}
    /** Descripción: Valida las condiciones necesarias para «validateRules» y rechaza entradas no válidas. Entradas: rules: dato de entrada necesario para la operación. Salida: no devuelve valor; completa la operación o comunica el fallo mediante el contrato existente. */ private void validateRules(List<HydraPolicyRule> rules){Map<String,Boolean> ids=new LinkedHashMap<>();for(HydraPolicyRule rule:rules){if(rule==null||rule.kind()==null)throw new IllegalArgumentException("Policy bundle contains an invalid rule");String id=HydraPersistenceSupport.safeId(rule.id(),"ruleId");if(ids.put(id,Boolean.TRUE)!=null)throw new IllegalArgumentException("Policy bundle contains duplicate rule IDs");}}
    /** Descripción: Valida las condiciones necesarias para «validateRevocations» y rechaza entradas no válidas. Entradas: values: colección de elementos que debe procesarse. Salida: no devuelve valor; completa la operación o comunica el fallo mediante el contrato existente. */ private void validateRevocations(List<HydraRevocationEntry> values){Map<String,Boolean> ids=new LinkedHashMap<>();for(HydraRevocationEntry item:values){if(item==null)throw new IllegalArgumentException("Policy bundle contains an invalid revocation");String id=HydraPersistenceSupport.safeId(item.id(),"revocationId");if(item.subjectId().isBlank()&&item.subjectSha256().isBlank())throw new IllegalArgumentException("Policy bundle revocation requires subject evidence");if(ids.put(id,Boolean.TRUE)!=null)throw new IllegalArgumentException("Policy bundle contains duplicate revocation IDs");}}
    /** Descripción: Ejecuta la operación «attestation» correspondiente a la responsabilidad de HydraPolicyBundleService. Entradas: id: identificador que delimita el recurso objetivo; version: dato de entrada necesario para la operación; channel: dato de entrada necesario para la operación; rules: dato de entrada necesario para la operación; revocations: dato de entrada necesario para la operación; annotations: dato de entrada necesario para la operación. Salida: devuelve el resultado definido por el contrato del método. */ private String attestation(String id,String version,Object channel,List<HydraPolicyRule> rules,List<HydraRevocationEntry> revocations,Map<String,String> annotations){return HydraPersistenceSupport.fingerprint(writer,Map.of("bundleId",id,"version",version,"channel",channel,"rules",rules,"revocations",revocations,"annotations",annotations));}
    /** Descripción: Ejecuta la operación «copy» correspondiente a la responsabilidad de HydraPolicyBundleService. Entradas: value: valor de entrada que debe procesarse; status: dato de entrada necesario para la operación; reason: dato de entrada necesario para la operación; activatedAt: dato de entrada necesario para la operación; revokedAt: dato de entrada necesario para la operación. Salida: devuelve el resultado definido por el contrato del método. */ private HydraPolicyBundle copy(HydraPolicyBundle value,HydraPolicyBundleStatus status,String reason,Instant activatedAt,Instant revokedAt){return new HydraPolicyBundle(value.bundleId(),value.version(),value.channel(),status,value.rules(),value.revocations(),value.attestationSha256(),reason,value.annotations(),value.createdAt(),activatedAt,revokedAt);}
    /** Descripción: Ejecuta la operación «same» correspondiente a la responsabilidad de HydraPolicyBundleService. Entradas: left: dato de entrada necesario para la operación; right: dato de entrada necesario para la operación. Salida: devuelve un indicador que expresa el resultado de la condición. */ private boolean same(HydraPolicyBundle left,HydraPolicyBundle right){return left.bundleId().equals(right.bundleId())&&left.version().equals(right.version());}
    /** Descripción: Obtiene la información correspondiente a «readAll» dentro de HydraPolicyBundleService. Entradas: root: ruta o ubicación utilizada por la operación; type: dato de entrada necesario para la operación. Salida: devuelve el resultado definido por el contrato del método. */ private <T> List<T> readAll(Path root,Class<T> type){List<T> result=new ArrayList<>();for(Path path:HydraPersistenceSupport.jsonFiles(root))try{result.add(mapper.readValue(com.example.editor.io.BoundedIo.readInternal(path),type));}catch(Exception ignored){com.example.editor.observability.HydraBestEffortDiagnostics.record("com/example/editor/policy/bundle/HydraPolicyBundleService.java",ignored);}return result;}
    /** Descripción: Obtiene la información correspondiente a «read» dentro de HydraPolicyBundleService. Entradas: path: ruta o ubicación utilizada por la operación; type: dato de entrada necesario para la operación; message: dato de entrada necesario para la operación. Salida: devuelve el resultado definido por el contrato del método. */ private <T> T read(Path path,Class<T> type,String message){try{return mapper.readValue(com.example.editor.io.BoundedIo.readInternal(path),type);}catch(Exception exception){throw new IllegalArgumentException(message,exception);}}
    /** Descripción: Actualiza el estado gestionado por HydraPolicyBundleService mediante la operación «write». Entradas: path: ruta o ubicación utilizada por la operación; value: valor de entrada que debe procesarse. Salida: no devuelve valor; completa la operación o comunica el fallo mediante el contrato existente. */ private void write(Path path,Object value){try{HydraPersistenceSupport.atomicWrite(path,writer.writeValueAsBytes(value));}catch(Exception exception){throw new IllegalStateException("Could not persist policy bundle evidence",exception);}}
    /** Descripción: Ejecuta la operación «bundlesRoot» correspondiente a la responsabilidad de HydraPolicyBundleService. Entradas: no requiere parámetros de entrada. Salida: devuelve el resultado definido por el contrato del método. */ private Path bundlesRoot(){return properties.getStorageRoot().resolve("versions");} /** Descripción: Ejecuta la operación «simulationsRoot» correspondiente a la responsabilidad de HydraPolicyBundleService. Entradas: no requiere parámetros de entrada. Salida: devuelve el resultado definido por el contrato del método. */ private Path simulationsRoot(){return properties.getStorageRoot().resolve("simulations");}
    /** Descripción: Ejecuta la operación «bundlePath» correspondiente a la responsabilidad de HydraPolicyBundleService. Entradas: id: identificador que delimita el recurso objetivo; version: dato de entrada necesario para la operación. Salida: devuelve el resultado definido por el contrato del método. */ private Path bundlePath(String id,String version){return bundlesRoot().resolve(id.replace(':','_')+"--"+version+".json");} /** Descripción: Ejecuta la operación «simulationPath» correspondiente a la responsabilidad de HydraPolicyBundleService. Entradas: id: identificador que delimita el recurso objetivo. Salida: devuelve el resultado definido por el contrato del método. */ private Path simulationPath(String id){return simulationsRoot().resolve(id+".json");}
}
